<style>
.ov-wrap{max-width:1280px;margin:auto;color:var(--text-primary)}.ov-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:26px;flex-wrap:wrap}.ov-head h1{font-size:30px;font-weight:750;letter-spacing:-.035em;margin:0 0 6px}.ov-muted{color:var(--text-muted);font-size:13px;line-height:1.6}.ov-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.ov-panel{background:var(--bg-card);border:1px solid var(--border-glass);border-radius:18px;padding:24px}.ov-panel h2{font-size:17px;font-weight:700;margin:0 0 8px}.ov-count{border-top:3px solid var(--ov-color,#3b82f6)}.ov-count strong{display:block;font-size:32px;letter-spacing:-.04em;margin:10px 0}.ov-count i{color:var(--ov-color)}.ov-columns{display:grid;grid-template-columns:1.1fr 1fr;gap:22px;margin-bottom:24px}.ov-usage{padding:18px 0;border-bottom:1px solid var(--border-glass)}.ov-usage:last-child{border:0}.ov-line{display:flex;align-items:center;justify-content:space-between;gap:14px}.ov-meter{height:7px;border-radius:10px;background:var(--bg-glass-input);overflow:hidden;margin-top:10px}.ov-meter span{height:100%;display:block;background:var(--ov-color);border-radius:10px}.ov-folder{display:block;text-decoration:none;color:var(--text-primary);border:1px solid var(--border-glass);border-left:4px solid var(--ov-color);border-radius:12px;padding:16px;transition:background .18s}.ov-folder:hover{background:var(--bg-glass-hover)}.ov-folders{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px}.ov-recent{padding:15px 0;border-bottom:1px solid var(--border-glass);display:flex;justify-content:space-between;gap:14px}.ov-recent a{color:var(--text-primary);font-weight:600}.ov-tabs{display:flex;gap:8px;margin-bottom:22px}.ov-tabs a{padding:10px 22px;border-radius:10px;border:1px solid var(--border-glass);color:var(--text-primary);text-decoration:none}.ov-tabs a[aria-current=page]{background:var(--accent);color:white}.ov-bars{display:flex;align-items:flex-end;gap:5px;height:150px;margin:20px 0 12px}.ov-bar{flex:1;min-width:0;background:#6366f1;border-radius:5px 5px 0 0}.ov-breakdown{padding:11px 0;border-bottom:1px solid var(--border-glass);font-size:13px;overflow-wrap:anywhere}.ov-empty{padding:35px 10px;text-align:center;color:var(--text-muted)}.ov-report-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:20px 0}.ov-attention{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.ov-attention a{padding:10px 14px;border:1px solid var(--border-glass);border-radius:10px;color:var(--text-primary)}
@media(max-width:900px){.ov-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ov-columns,.ov-report-grid{grid-template-columns:1fr}}@media(max-width:520px){.ov-panel{padding:18px}.ov-folders{grid-template-columns:1fr}.ov-head h1{font-size:25px}}@media(prefers-reduced-motion:reduce){.ov-folder{transition:none}}
.ov-count i{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:12px;background:color-mix(in srgb,var(--ov-color) 12%,transparent)}.ov-folder{transition:background .18s,transform .18s,box-shadow .18s}.ov-folder:hover{transform:translateY(-2px);box-shadow:0 6px 18px rgba(0,0,0,.06)}.ov-wrap a:focus-visible,.ov-wrap summary:focus-visible{outline:2px solid var(--accent,#3b82f6);outline-offset:4px}.ov-recent>div{min-width:0}.ov-recent a{overflow-wrap:anywhere}.ov-meter span{transition:width .35s ease}.ov-panel{animation:ov-enter .25s ease both}@keyframes ov-enter{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.ov-panel{animation:none}.ov-folder,.ov-meter span{transition:none}.ov-folder:hover{transform:none}}

/* Workspace inventory cards: sculpted illustrations, no decorative analytics. */
.ov-count{position:relative;isolation:isolate;overflow:hidden;min-height:190px;padding:18px;border:1px solid rgba(255,255,255,.16);border-radius:22px;color:#fff;background:radial-gradient(ellipse at 95% 0%,color-mix(in srgb,var(--ov-color) 85%,white) 0%,transparent 70%),linear-gradient(145deg,var(--ov-tone),color-mix(in srgb,var(--ov-tone) 90%,#0b1020));box-shadow:0 12px 24px color-mix(in srgb,var(--ov-tone) 16%,transparent),inset 0 1px 0 rgba(255,255,255,.22);transition:transform .3s ease,box-shadow .3s ease}
.ov-count::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(130deg,rgba(255,255,255,.10),transparent 42%,rgba(255,255,255,.04));pointer-events:none}
.ov-count-top{display:flex;align-items:center;justify-content:space-between;gap:8px;position:relative;z-index:2}.ov-panel .ov-count-label{font-size:15px;line-height:1.3;font-weight:650;letter-spacing:-.015em;margin:0;color:#fff}
.ov-count-art{position:absolute;right:-14px;top:30px;width:110px;height:82px;opacity:.95;pointer-events:none;transition:transform .45s cubic-bezier(.2,.8,.2,1);filter:drop-shadow(0 14px 12px rgba(0,0,0,.20))}.ov-count-bottom{position:relative;z-index:2;padding-top:56px}.ov-count strong{display:block;font-size:min(clamp(38px,3.7vw,54px),var(--ov-number-size,54px));font-weight:750;line-height:1;letter-spacing:-.05em;margin:0;font-variant-numeric:tabular-nums;text-shadow:0 2px 10px rgba(0,0,0,.08);overflow-wrap:anywhere}.ov-count-bottom p{font-size:11px;font-weight:500;color:rgba(255,255,255,.85);margin:10px 0 0;letter-spacing:.01em}.ov-count:hover{transform:translateY(-4px);box-shadow:0 18px 32px color-mix(in srgb,var(--ov-tone) 24%,transparent),inset 0 1px 0 rgba(255,255,255,.28)}.ov-count:hover .ov-count-art{transform:translate(-3px,-7px) rotate(-4deg)}
@media(max-width:1100px) and (min-width:901px){.ov-count{padding:18px}.ov-count-art{width:105px;right:-10px;top:30px}}
@media(max-width:520px){.ov-count{min-height:175px;padding:16px}.ov-count-art{width:92px;height:72px;right:-7px;top:34px}.ov-count-bottom{padding-top:50px}.ov-count strong{font-size:min(38px,var(--ov-number-size,54px))}}
.ov-folder{position:relative;border-left:1px solid var(--border-glass);padding:14px 18px 18px;background:linear-gradient(155deg,color-mix(in srgb,var(--ov-color) 7%,var(--bg-card)),var(--bg-card));overflow:hidden}.ov-folder-art{display:block;width:150px;max-width:100%;height:auto;margin:0 auto 8px;color:var(--ov-color);filter:drop-shadow(0 6px 8px color-mix(in srgb,var(--ov-color) 15%,transparent))}.ov-folder-caption{display:flex;flex-direction:column;gap:3px;padding-right:18px}.ov-folder-caption strong{overflow-wrap:anywhere;font-size:15px}.ov-folder-arrow{position:absolute;bottom:25px;right:18px;color:var(--ov-color);font-size:20px}.ov-folder-paper,.ov-folder-cover{transition:transform .3s cubic-bezier(.2,.8,.2,1);transform-box:fill-box;transform-origin:center bottom}.ov-folder:is(:hover,:focus-visible) .ov-folder-paper-back{transform:translateY(-12px) rotate(-6deg)}.ov-folder:is(:hover,:focus-visible) .ov-folder-paper-front{transform:translateY(-7px) rotate(3deg)}.ov-folder:is(:hover,:focus-visible) .ov-folder-cover{transform:scaleY(.92) skewX(-2deg)}
@media(prefers-reduced-motion:reduce){.ov-count,.ov-count-art,.ov-folder-paper,.ov-folder-cover{transition:none}.ov-count:hover,.ov-count:hover .ov-count-art,.ov-folder:is(:hover,:focus-visible) .ov-folder-paper,.ov-folder:is(:hover,:focus-visible) .ov-folder-cover{transform:none}}
</style>
